<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"/>
<title>Booger Dodge</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@600;700&family=Nunito:wght@800&display=swap');
:root{--ink:#26324a;--mint:#79dbb5;--cream:#fff8df}
*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden}body{font-family:Fredoka,Nunito,sans-serif;background:#9fdac6;color:var(--ink)}
#game{position:relative;width:100vw;height:100vh;overflow:hidden;background:linear-gradient(#bbebd4 0 13%,#89cfb2 13% 100%)}
#game:before{content:"";position:absolute;inset:0 0 87% 0;background:linear-gradient(90deg,rgba(255,255,255,.24) 50%,transparent 50%) 0 0/76px 76px;opacity:.8}
.board{position:absolute;left:50%;top:50%;width:min(94vw,1120px);height:min(82vh,720px);transform:translate(-50%,-50%);border:6px solid #26324a;border-radius:28px;background:#d8efb8;box-shadow:0 10px 0 #5c9d86,0 18px 40px rgba(38,50,74,.18);overflow:hidden}
.grid{position:absolute;inset:0;opacity:.18;background-image:linear-gradient(#70ad91 2px,transparent 2px),linear-gradient(90deg,#70ad91 2px,transparent 2px);background-size:44px 44px}
.hud{position:absolute;z-index:20;left:18px;right:18px;top:14px;display:flex;justify-content:space-between;pointer-events:none}.pill{height:48px;border:4px solid var(--ink);border-radius:18px;background:#fffdf3;display:flex;align-items:center;gap:9px;padding:0 14px;font-size:19px;box-shadow:0 5px 0 rgba(38,50,74,.14)}.pill b{font-size:24px}.heart{color:#f06d73;font-size:24px}.clock{color:#4aa78a}
#canvas{position:absolute;inset:0;width:100%;height:100%}
.overlay{position:absolute;z-index:40;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(133,202,178,.3);backdrop-filter:blur(3px)}.overlay.hidden{display:none}.card{width:min(440px,86vw);text-align:center;border:6px solid var(--ink);border-radius:32px;background:#fffbed;padding:28px 28px 24px;box-shadow:0 12px 0 #6aa68f,0 22px 30px rgba(38,50,74,.16)}.face{width:108px;height:108px;margin:-76px auto 8px;border:6px solid var(--ink);border-radius:50%;background:#b8df78;position:relative;box-shadow:0 7px 0 #78aa66}.face:before,.face:after{content:"";position:absolute;width:17px;height:22px;background:var(--ink);border-radius:50%;top:30px}.face:before{left:28px}.face:after{right:28px}.face i{position:absolute;width:34px;height:14px;border-bottom:5px solid var(--ink);border-radius:50%;left:37px;bottom:25px}.face .boog{position:absolute;width:44px;height:31px;right:-23px;bottom:9px;border:5px solid var(--ink);border-radius:60% 55% 70% 45%;background:#f0dd52;transform:rotate(-10deg)}h1{font-size:48px;line-height:.9;margin:16px 0 8px;letter-spacing:-2px}p{margin:8px 0 18px;font-size:17px}.best{color:#6a7a78;font-size:14px}.start{border:4px solid var(--ink);border-radius:18px;background:#f7ca58;color:var(--ink);font-family:inherit;font-size:22px;font-weight:700;padding:11px 30px 9px;box-shadow:0 6px 0 #b68f3c;cursor:pointer}.start:active{transform:translateY(4px);box-shadow:0 2px 0 #b68f3c}
.controls{position:absolute;z-index:30;bottom:14px;left:18px;display:none;gap:8px}.ctrl{width:60px;height:60px;border:4px solid var(--ink);border-radius:16px;background:rgba(255,253,243,.88);font-size:26px;color:var(--ink);touch-action:none;box-shadow:0 5px 0 rgba(38,50,74,.2)}
@media(max-width:700px),(pointer:coarse){.board{width:100vw;height:100vh;top:0;left:0;transform:none;border:0;border-radius:0}.hud{top:10px}.pill{height:42px;font-size:15px;border-width:3px}.pill b{font-size:19px}.controls{display:flex}.card h1{font-size:40px}.card{padding-top:24px}}
</style></head>
<body><main id="game"><div class="board" id="board"><div class="grid"></div>
<div class="hud"><div class="pill">RUN <b id="time">0:00</b></div><div class="pill"><span class="heart">♥</span><b id="life">3</b></div></div>
<canvas id="canvas"></canvas>
<div class="overlay" id="overlay"><div class="card"><div class="face"><i></i><span class="boog"></span></div><h1 id="title">Booger Dodge</h1><p id="message">Don't let the sneaky booger touch you!</p><div class="best" id="best">BEST RUN — 0:00</div><br/><button class="start" id="start">START RUN</button></div></div>
<div class="controls"><button class="ctrl" data-key="left">◀</button><button class="ctrl" data-key="right">▶</button></div>
</div></main>
<script>
const canvas=document.getElementById('canvas'),ctx=canvas.getContext('2d'),board=document.getElementById('board'),overlay=document.getElementById('overlay'),timeEl=document.getElementById('time'),lifeEl=document.getElementById('life'),bestEl=document.getElementById('best');
let w,h,dpr,player,booger,keys={},running=false,startTime=0,elapsed=0,lives=3,invincible=0,last=0,boogers=[],particles=[];let best=+(localStorage.getItem('boogerBest')||0);
function resize(){let r=board.getBoundingClientRect();w=r.width;h=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}resize();addEventListener('resize',resize);
function fmt(s){let m=Math.floor(s/60),sec=Math.floor(s%60);return m+':'+String(sec).padStart(2,'0')}bestEl.textContent='BEST RUN — '+fmt(best);
function reset(){player={x:w*.5,y:h*.68,r:24,vx:0,vy:0,face:1};booger={x:w*.5,y:h*.28,r:38,vx:0,vy:0};boogers=[booger];particles=[];lives=3;elapsed=0;invincible=0;lifeEl.textContent=lives}
function start(){reset();running=true;startTime=performance.now();overlay.classList.add('hidden')}
document.getElementById('start').onclick=start;
addEventListener('keydown',e=>{keys[e.key.toLowerName||e.key]=true;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','a','d','w','s'].includes(e.key))e.prevent.preventDefault();if(!running&&(e.key==='Enter'||e.key===' '))start()});
addEventListener('keyup',e=>keys[e.key]=false);
// Pointer joystick-style controls: drag anywhere on lower board
board.addEventListener('pointerdown',e=>{if(!running)return;const r=board.getBoundingClientRect();keys._px=e.clientX-r.left;keys._py=e.clientY-r.top});board.addEventListener('pointermove',e=>{if(!running||keys._px==null)return;const r=board.getBoundingClientRect();keys._px=e.clientX-r.left;keys._py=e.clientY-r.top});board.addEventListener('pointerup',()=>{keys._px=null;keys._py=null});
document.querySelectorAll('.ctrl').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();keys[b.dataset.key]=true});b.addEventListener('pointerup',()=>keys[b.dataset.key]=false);b.addEventListener('pointerleave',()=>keys[b.dataset.key]=false)});
function dust(x,y,c){for(let i=0;i<8;i++)particles.push({x,y,vx:(Math.random()-0.5)*180,vy:(Math.random()-0.7)*150,a:1,c})}
function drawPlayer(p){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.vx*.015);ctx.globalAlpha=invincible>0&&Math.floor(invincible*12)%2?0.35:1;ctx.fillStyle='#69c38d';ctx.strokeStyle='#26324a';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,p.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#26324a';ctx.beginPath();ctx.arc(-9,-6,4,0,7);ctx.arc(9,-6,4,0,7);ctx.fill();ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,5,10,.15*Math.PI,.85*Math.PI);ctx.stroke();ctx.restore()}
function drawBooger(b,i){ctx.save();ctx.translate(b.x,b.y);let ang=Math.atan2(b.vy,b.vx);ctx.rotate(ang*.12);ctx.fillStyle=i?'#91cd68':'#b9dc67';ctx.strokeStyle='#26324a';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-b.r*.65,-b.r*.3);ctx.bezierCurveTo(-b.r,-b.r*.9,b.r*.15,-b.r*1.05,b.r*.45,-b.r*.45);ctx.bezierCurveTo(b.r*1.15,-b.r*.25,b.r*.95,b.r*.75,b.r*.35,b.r*.65);ctx.bezierCurveTo(-b.r*.15,b.r*1.15,-b.r*.95,b.r*.55,-b.r*.65,-b.r*.3);ctx.fill();ctx.stroke();ctx.fillStyle='#26324a';ctx.beginPath();ctx.arc(-11,-7,5,0,7);ctx.arc(12,-7,5,0,7);ctx.fill();ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,10,9,.1*Math.PI,.9*Math.PI);ctx.stroke();ctx.restore()}
function update(dt){elapsed=(performance.now()-startTime)/1000;timeEl.textContent=fmt(elapsed);
let ax=0,ay=0;if(keys.ArrowLeft||keys.a||keys.left)ax-=1;if(keys.ArrowRight||keys.d||keys.right)ax+=1;if(keys.ArrowUp||keys.w)ay-=1;if(keys.ArrowDown||keys.s)ay+=1;if(keys._px!=null){ax+=(keys._px-player.x)/150;ay+=(keys._py-player.y)/150;let m=Math.hypot(ax,ay);if(m>1){ax/=m;ay/=m}}let speed=250;player.vx+=(ax*speed-player.vx)*Math.min(1,dt*9);player.vy+=(ay*speed-player.vy)*Math.min(1,dt*9);player.x+=player.vx*dt;player.y+=player.vy*dt;player.x=Math.max(player.r+8,Math.min(w-player.r-8,player.x));player.y=Math.max(68+player.r,Math.min(h-player.r-8,player.y));
// Enemy accelerates toward player, with extra speed and bonus enemies over time
let difficulty=1+elapsed*.018;boogers.forEach((b,i)=>{let dx=player.x-b.x,dy=player.y-b.y,d=Math.max(1,Math.hypot(dx,dy));b.vx+=(dx/d*(100+elapsed*2.2+i*18)-b.vx)*Math.min(1,dt*(1.3+difficulty*.12));b.vy+=(dy/d*(100+elapsed*2.2+i*18)-b.vy)*Math.min(1,dt*(1.3+difficulty*.12));b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.x<b.r||b.x>w-b.r)b.vx*=-1;if(b.y<68+b.r||b.y>h-b.r)b.vy*=-1;b.x=Math.max(b.r,Math.min(w-b.r,b.x));b.y=Math.max(68+b.r,Math.min(h-b.r,b.y));if(Math.hypot(player.x-b.x,player.y-b.y)<player.r+b.r*.72&&invincible<=0){lives--;lifeEl.textContent=lives;invincible=1.7;dust(player.x,player.y,'#ffde67');b.x=w*.5;b.y=h*.18;b.vx=(Math.random()-.5)*100;b.vy=100;if(lives<=0)end()}});
// introduce a second/third enemy
if(elapsed>18&&!boogers[1])boogers.push({x:w*.15,y:h*.25,r:34,vx:70,vy:70});if(elapsed>42&&!boogers[2])boogers.push({x:w*.85,y:h*.2,r:31,vx:-70,vy:80});if(invincible>0)invincible-=dt;particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.a-=dt*1.5});particles=particles.filter(p=>p.a>0)}
function end(){running=false;if(elapsed>best){best=elapsed;localStorage.setItem('boogerBest',best)}bestEl.textContent='BEST RUN — '+fmt(best);document.getElementById('title').textContent='Gotcha!';document.getElementById('message').textContent='You lasted '+fmt(elapsed)+'. Try to outrun that booger!';document.getElementById('start').textContent='TRY AGAIN';overlay.classList.remove('hidden')}
function draw(){ctx.clearRect(0,0,w,h);particles.forEach(p=>{ctx.globalAlpha=Math.max(0,p.a);ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,5,0,7);ctx.fill()});ctx.globalAlpha=1;boogers.forEach((b,i)=>drawBooger(b,i));drawPlayer(player)}
function loop(t){let dt=Math.min(.033,(t-last)/1000||0);last=t;if(running)update(dt);draw();requestAnimationFrame(loop)}reset();draw();requestAnimationFrame(loop);
</script></body></html>
EOF
